/**
 * @name Command injection in click CLI toolkit
 * @description User input flowing to subprocess/shell execution within click
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-click
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ClickCommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for subprocess calls within click package
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["call", "Popen", "run", "check_output"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember(["system", "popen"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module ClickCommandInjectionFlow = TaintTracking::Global<ClickCommandInjectionConfig>;
import ClickCommandInjectionFlow::PathGraph

from ClickCommandInjectionFlow::PathNode source, ClickCommandInjectionFlow::PathNode sink
where ClickCommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"
